export function enrichSolution(id,p,flags,r){
 if(flags.legacy)return r;
 const m=p.mass||1,G=9.8,put=(key,value,unit='')=>({key,value,unit});
 const stat=(rig,outcome,metrics)=>({...r,cart:false,dynamic:false,rig,outcome,metrics});
 if(id==='curling'){const f=p.force,motion=cartStoppingMotion(id,f,1);return {...r,rig:'cart',cart:true,dynamic:true,mass:1,duration:motion.duration,forces:[{mag:f,angle:p.direction<0?180:0,attach:0},{mag:0,angle:0,attach:0},{mag:0,angle:0,attach:0}],metrics:[put('displacement',motion.displacement,'m')],outcome:p.direction<0?'leftMoves':'rightMoves'};}
 if(id==='represent')return {...r,rig:'cart',cart:true,dynamic:false,forces:[{mag:p.magnitude,angle:p.direction<0?180:0,attach:0},{mag:0,angle:0,attach:0},{mag:0,angle:0,attach:0}],metrics:[put('force',p.magnitude,'N')],outcome:'drawing'};
 if(id==='parallel'&&p.arrangement==='same'){const net=p.right+p.left;return {...r,forces:[{mag:p.right,angle:0,attach:0},{mag:p.left,angle:0,attach:0},{mag:0,angle:0,attach:0}],metrics:[put('net',net,'N'),put('speed',(p.initial||0)+net*1.2,'m/s')],outcome:'rightMoves'};}
 if(id==='balance'||id==='mobile'){const torque=p.left*(p.leftPos||2)-p.right*(p.rightPos||2);return stat(id==='mobile'?'mobile':'balance',Math.abs(torque)<1e-8?'balanced':torque>0?'leftHeavy':'rightHeavy',[put('leftLoad',p.left,'g'),put('rightLoad',p.right,'g')]);}
 if(id==='scale'||id==='spring-scale'){const grams=OBJECTS[p.object]??p.grams;return stat(id==='scale'?'scale':'spring-scale',!flags.zeroed?'zeroNeed':!flags.placed?'zeroDone':'reading',[put('reading',flags.zeroed?(flags.placed?grams:0):null,'g'),put('unitTicks',id==='spring-scale'?5:1,'g')]);}
 if(id==='tools'||id==='ramp-tools'){const ratio=p.tool==='direct'?1:.5/p.length;return {...stat(p.tool==='direct'?'direct':p.tool==='lever'?'lever-lift':p.tool,'lifted',[put('direct',m,'relative'),put('withTool',m*ratio,'relative'),put('distance',p.tool==='direct'?.5:p.length,'m')]),cart:p.tool==='ramp'};}
 if(id==='review')return stat('inference',p.example==='bottle'?'inferenceLeft':'inferenceLevel',[put('comparisons',p.example==='forklift'?2:1)]);
 if(id==='daily-tools'||id==='applications')return stat('examples','sample',[put('sample',1)]);
 if(id==='wearable')return stat('assist','lifted',[put('forceComparison',m*(p.method==='robot'?.3:1),'relative')]);
 if(id==='gravity-direction')return stat('globe','toCenter',[put('weight',G,'N')]);
 if(id==='elastic-shape')return stat('deform',p.shape==='release'?'returns':'deformed',[put('forceComparison',p.shape==='release'?0:(p.deformation||1),'relative')]);
 if(id==='elastic'&&p.springMode==='stretch')return stat('spring','springDirection',[put('extension',p.extension,'cm'),put('springForce',p.k*p.extension/100,'N')]);
 if(id==='friction')return stat('friction','starts',[put('startForce',p.surface*m*G,'N'),put('massScience',m,'kg')]);
 if(id==='buoyancy'){const b=p.density*G*p.volume/1e6;return stat('tank','buoyancyDirection',[put('airScale',G,'N'),put('scale',G-b,'N'),put('difference',b,'N'),put('buoyancy',b,'N'),put('weight',G,'N')]);}
 if(id==='overflow'){const b=1000*G*p.volume/1e6;return stat('overflow','buoyancyDirection',[put('airScale',G,'N'),put('scale',G-b,'N'),put('emptyCup',.98,'N'),put('fullCup',.98+b,'N'),put('waterWeight',b,'N'),put('difference',b,'N')]);}
 if(['floating','diver-intro','review-middle'].includes(id)){const b=p.case==='balloon'?1.2*G*.005:p.case==='submarine'?1000*G*.004:1000*G*(900+p.volume)/1e6,w=p.case==='balloon'?(.0021+.18*.005+p.clips*.001)*G:p.case==='submarine'?(3+p.fill*.5)*G:G;return stat('floating',Math.abs(b-w)<1e-8?'still':b>w?'up':'down',[put('weight',w,'N'),put('buoyancy',b,'N'),put('net',b-w,'N')]);}
 if(id==='motion'){const angle={speedup:0,slowdown:180,turn:90,stop:180}[p.mode],initial=p.initial??1,f=p.mode==='stop'?initial/1.2:.6;return {...r,rig:'ball',cart:false,dynamic:true,initialVelocity:initial,mass:1,forces:[{mag:f,angle,attach:0},{mag:0,angle:0,attach:0},{mag:0,angle:0,attach:0}],metrics:[put('speed',Math.hypot(initial+f*1.2*Math.cos(angle*Math.PI/180),f*1.2*Math.sin(angle*Math.PI/180)),'m/s')],outcome:p.mode==='stop'?'still':p.mode};}
 if(id==='contact')return stat('support','heldStill',[put('weight',m*G,'N'),put('normal',m*G,'N'),put('net',0,'N')]);
 if(id==='motion-classify')return stat('motion-classify',{falling:'speedOnly',circle:'directionOnly',projectile:'bothChange'}[p.mode],[put('speedChange',p.mode==='circle'?0:1),put('directionChange',p.mode==='falling'?0:1)]);
 if(id==='design'){const device=p.device||'brake',speed=p.speed||1.5,k=p.k||20,compression=Math.sqrt(m*speed**2/k),distance=device==='bumper'?.3+compression:speed**2/(2*p.surface*G);return stat('design',distance<=1?'stable':'tips',[put('displacement',distance,'m'),put('forceComparison',device==='brake'?p.surface*m*G:k*compression,'N')]);}
 if(id==='turning'&&['same','opposite'].includes(p.mode)){const angle=p.mode==='same'?0:180,net=p.right+(angle===0?p.left:-p.left);return {...r,rig:'cart',cart:true,dynamic:true,mass:1,initialVelocity:0,duration:1.2,forces:[{mag:p.right,angle:0,attach:0},{mag:p.left,angle,attach:0},{mag:0,angle:0,attach:0}],metrics:[put('net',net,'N'),put('speed',net*1.2,'m/s')],outcome:net===0?'still':net>0?'rightMoves':'leftMoves'};}
 if(id==='turning')return stat('turning','rotates',[put('torque',p.effort*p.reach*Math.sin(p.angle*Math.PI/180),'N·m')]);
 if(id==='lever-counts'||id==='review-high'){const l=p.leftCount*p.leftPos,rr=p.rightCount*p.rightPos;return stat(id==='review-high'?'crane':'beam-counts',l===rr?'level':l>rr?'counter':'clockwise',[put('leftProduct',l),put('rightProduct',rr),put('torque',(l-rr)*.098,'N·m'),put('net',0,'N'),put('reaction',(p.leftCount+p.rightCount)*.98,'N')]);}
 if(id==='torque'&&p.mode&&p.mode!=='beam'){const angle=p.mode==='same'?0:180,net=p.right+(angle===0?p.left:-p.left);return {...r,rig:'cart',cart:true,dynamic:true,mass:1,initialVelocity:0,duration:1.2,forces:[{mag:p.right,angle:0,attach:0},{mag:p.left,angle,attach:0},{mag:0,angle:0,attach:0}],metrics:[put('net',net,'N'),put('speed',net*1.2,'m/s')],outcome:net===0?'still':net>0?'rightMoves':'leftMoves'};}
 if(id==='couple')return stat('couple',p.line==='separated'?'rotates':'still',[put('net',0,'N'),put('torque',p.line==='separated'?-p.effort:0,'N·m')]);
 if(id==='shelf'){const rope=p.load*p.position/p.length;return stat('shelf','heldStill',[put('wallReaction',p.load-rope,'N'),put('ropeForce',rope,'N'),put('net',0,'N'),put('torque',0,'N·m')]);}
 if(id==='stability'){const side=p.offset<0?-1:1,edge=side*p.width/2,theta=(p.tilt||0)*Math.PI/180,projection=edge+(p.offset-edge)*Math.cos(theta)+side*(p.height||2)/2*Math.sin(theta),gap=p.width/2-Math.abs(projection);return stat('stability',Math.abs(gap)<1e-8?'edge':gap>0?'stable':'tips',[put('projection',projection,'m'),put('support',p.width,'m'),put('gravityMoment',p.tilt?-G*(projection-edge):0,'N·m')]);}
 return r;
}
